def rule_fn(row, col):
    val = row.get(col, "")
    if not isinstance(val, str):
        return False
    # Leading or trailing whitespace
    if val != val.strip():
        return True
    # Double spaces anywhere
    if "  " in val:
        return True
    # Two or more spaces after a period
    import re
    if re.search(r"\. {2,}", val):
        return True
    # Missing space after period (e.g., "word.Another")
    if re.search(r"[A-Za-z]\.[A-Za-z]", val):
        return True
    return False

def rule_fn(row, col):
    if col != 'Stateavg':
        return False
    import re
    v = str(row.get('Stateavg', ''))
    if v == '':
        return True
    # Expect state prefix (al or ak), underscore, then measure code slug
    return re.match(r'^(al|ak)_[a-z0-9\-]+$', v) is None

