def rule_fn(row, col):
    if col != 'MeasureName':
        return False
    import re
    v = str(row.get('MeasureName',''))
    # Flag any single-letter word tokens except 'a' or 'i'
    singles = re.findall(r'\b([A-Za-z])\b', v)
    for s in singles:
        if s.lower() not in {'a','i'}:
            return True
    return False

